import {DEFAULT_SETTINGS,EXAM_SPEC,DEFAULT_SECTIONS,applyAnswerKey,escapeHTML as esc,formatTime,planFor,newSession,currentQuestion,startSession,tickSession,accountTime,pauseSession,resumeSession,advanceSection,completeSession,scoreQuestions,Calculator,csvCell} from './core.js';
import {readRecord,writeRecord} from './storage.js';
import {sampleProject} from './samples.js';
import {initBuilder} from './builder.js';
import {initKeyDialog} from './keys-ui.js';
const $=id=>document.getElementById(id);
let project=sampleProject(),settings=structuredClone(DEFAULT_SETTINGS),session=newSession(),plan=planFor(project,settings),saveTimer,toastTimer,confirmResolve;
let scratch={memo:'',strokes:[]},paintMode='pen',activeStroke=null,lastRender='',saveSequence=Promise.resolve();
const calculator=new Calculator();
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,4500);}
function ask(title,text,ok='확인'){return new Promise(resolve=>{if(confirmResolve)confirmResolve(false);confirmResolve=resolve;$('confirmTitle').textContent=title;$('confirmText').textContent=text;$('confirmOk').textContent=ok;$('confirmDialog').showModal();});}
function resolveConfirm(value){$('confirmDialog').close();const fn=confirmResolve;confirmResolve=null;fn?.(value);}
$('confirmOk').onclick=()=>resolveConfirm(true);$('confirmCancel').onclick=()=>resolveConfirm(false);$('confirmDialog').addEventListener('cancel',e=>{e.preventDefault();resolveConfirm(false);});
function download(name,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function stateSnapshot(){return {projectId:project.id,settings:structuredClone(settings),session:structuredClone(session),scratch:structuredClone(scratch),savedAt:Date.now()};}
function saveImmediate(value=stateSnapshot()){try{localStorage.setItem('skct-current-session',JSON.stringify(value));}catch{/* IndexedDB remains the primary storage if synchronous storage is unavailable. */}return value;}
function queueSave(){saveImmediate();clearTimeout(saveTimer);saveTimer=setTimeout(()=>persist(),300);}
function persist(){const value=saveImmediate();saveSequence=saveSequence.catch(()=>{}).then(()=>writeRecord('state',value)).then(()=>{$('saveStatus').textContent='이 기기에 자동 저장됨';}).catch(()=>{$('saveStatus').textContent='저장 실패 · 문제집/결과를 내보내세요';});return saveSequence;}
async function persistProject(){try{await writeRecord('project',project);await persist();}catch{toast('저장 공간이 부족하거나 브라우저 저장이 차단되어 있습니다. 문제집을 내보내 백업하세요.');$('saveStatus').textContent='문제집 저장 실패 · 내보내기 필요';}}
const qNow=()=>currentQuestion(session,plan);
function isActive(){return ['running','break','paused'].includes(session.status);}
function sync(){const changed=tickSession(session,plan,settings,Date.now());if(changed){resetScratch();lastRender='';render();queueSave();if(session.status==='finished'){toast('제한 시간이 끝나 시험이 제출되었습니다.');showResults();}}return changed;}
function canAnswer(){sync();return session.status==='running';}
function resetScratch(){if(settings.clearTools){scratch={memo:'',strokes:[]};$('memo').value='';drawPaint();calculator.clear();renderCalculator();}}
function choose(value,id=qNow()?.id){if(!canAnswer())return toast('시험을 시작한 뒤 답안을 선택할 수 있습니다.');const list=plan[session.sectionIndex].questions;const index=list.findIndex(q=>q.id===id);if(index<0)return;if(!settings.allowBack&&index<session.index)return toast('현재 설정에서는 이전 문항의 답안을 바꿀 수 없습니다.');if(index!==session.index)navigate(index);session.answers[id]=session.answers[id]===value?null:value;renderAnswers();queueSave();}
const reviewing=()=>session.status==='finished';
/** Result of one question in review: correct / wrong / blank / ungraded. */
function verdict(q){const a=session.answers[q.id];return !q.key?'ungraded':!a?'blank':a===q.key?'correct':'wrong';}
// Review: the correct answer of a wrong/blank question stays hidden until '정답 확인' is pressed.
let revealedKeys=new Set();
function keyShown(q){return reviewing()&&!!q.key&&(verdict(q)==='correct'||revealedKeys.has(q.id));}
/** Review mode can move across sections as well. */
function goTo(sectionIndex,index){if(!plan[sectionIndex]?.questions[index])return;session.sectionIndex=sectionIndex;session.index=index;resetScratch();lastRender='';render();$('questionScroll').scrollTop=0;queueSave();}
function navigate(index){sync();if(['break','paused'].includes(session.status))return;const list=plan[session.sectionIndex]?.questions||[];if(index<0||index>=list.length)return;if(session.status==='running'&&!settings.allowBack&&index<session.index)return;accountTime(session,plan,Date.now());session.index=index;session.accountedUntil=Date.now();resetScratch();lastRender='';render();$('questionScroll').scrollTop=0;queueSave();}
function renderQuestion(){const q=qNow();if(!q)return;$('questionNumber').textContent=String(session.index+1).padStart(2,'0');$('questionTotal').textContent=`/ ${String(plan[session.sectionIndex].questions.length).padStart(2,'0')}`;$('sourceLabel').textContent=q.parts?.length?q.label:q.source;$('questionContent').replaceChildren();
 if(q.parts?.length){for(const part of q.parts){const img=document.createElement('img');img.src=part.src;img.alt=`${q.label} · 원본 ${part.page||'?'}쪽`;img.draggable=false;$('questionContent').append(img);}}
 else{$('questionContent').innerHTML=`<h2>${esc(q.title)}</h2>${q.passage?`<div class="passage">${esc(q.passage).replace(/\n/g,'<br>')}</div>`:''}${q.table?`<table><thead><tr>${q.table.headers.map(t=>`<th>${esc(t)}</th>`).join('')}</tr></thead><tbody>${q.table.rows.map(row=>`<tr>${row.map(t=>`<td>${esc(t)}</td>`).join('')}</tr>`).join('')}</tbody></table>`:''}${q.sequence?`<div class="figure-sequence">${esc(q.sequence)}</div>`:''}<div class="sample-options">${(q.options||[]).map((s,i)=>`<div class="sample-option"><b>${['①','②','③','④','⑤'][i]}</b><span>${esc(s)}</span></div>`).join('')}</div>`;}
 applyZoom();$('memo').value=scratch.memo;drawPaint();
}
function applyZoom(){const q=qNow(),v=$('zoomSelect').value,content=$('questionContent');content.classList.toggle('fit-image',v==='fit'&&!!q?.parts?.length);content.style.width=v==='fit'?'100%':v+'%';content.style.maxWidth=v==='fit'?'100%':'none';content.style.fontSize=v==='fit'?'17px':`${17*Number(v)/100}px`;}
function renderAnswers(){const q=qNow();if(!q)return;const disabled=session.status!=='running',review=reviewing(),mine=session.answers[q.id],v=verdict(q);
 $('answerChoices').innerHTML=[1,2,3,4,5].map(n=>{const shown=keyShown(q);const cls=[mine===n?'selected':'',shown&&q.key===n?'key':'',review&&mine===n&&q.key&&q.key!==n?'wrong':''].filter(Boolean).join(' ');const label=review?`${n}번${mine===n?' · 내 답':''}${shown&&q.key===n?' · 정답':''}`:`${n}번 선택`;return `<button aria-label="${label}" aria-pressed="${mine===n}" data-answer="${n}" class="${cls}" ${disabled?'disabled':''}>${n}${shown&&q.key===n?'<i>정답</i>':''}${review&&mine===n&&q.key!==n?'<i>내 답</i>':''}</button>`;}).join('');
 const C=['','①','②','③','④','⑤'];$('reviewInfo').hidden=!review;document.querySelector('.answer-bar').classList.toggle('reviewing',review);$('answerBarLabel').textContent=review?'채점 결과':'답안 선택';$('clearAnswerBtn').hidden=review;
 if(review){$('reviewInfo').className=`review-info ${v}`;$('reviewInfo').innerHTML=`<span>내 답 <b>${mine?C[mine]:'—'}</b></span><span>정답 ${!q.key?'<b>미입력</b>':keyShown(q)?`<b>${C[q.key]}</b>`:'<button id="revealKeyBtn" class="reveal-key">정답 확인</button>'}</span><strong>${{correct:'정답',wrong:'오답',blank:'미응답 (오답)',ungraded:'미채점'}[v]}</strong>`;}$('clearAnswerBtn').disabled=disabled;$('flagBtn').classList.toggle('active',!!session.flags[q.id]);$('flagBtn').setAttribute('aria-pressed',!!session.flags[q.id]);$('flagBtn').textContent=session.flags[q.id]?'★ 다시 보기':'☆ 다시 보기';$('flagBtn').disabled=!['running','ready'].includes(session.status);
 const list=plan[session.sectionIndex].questions;$('answeredCount').textContent=`${list.filter(q=>session.answers[q.id]).length} / ${list.length}`;const oldScroll=$('omrGrid').scrollTop;
 $('omrGrid').innerHTML=list.map((q,i)=>{const locked=session.status!=='running'||(!settings.allowBack&&i<session.index);return `<div class="omr-row ${i===session.index?'current':''}"><button class="omr-number" data-go="${i}" aria-label="${i+1}번 문항으로 이동" ${['paused','break'].includes(session.status)||(session.status==='running'&&!settings.allowBack&&i<session.index)?'disabled':''}>${String(i+1).padStart(2,'0')}</button>${[1,2,3,4,5].map(n=>`<button class="omr-choice ${session.answers[q.id]===n?'selected':''} ${keyShown(q)&&q.key===n?'key':''} ${reviewing()&&session.answers[q.id]===n&&q.key&&q.key!==n?'wrong':''}" data-q="${esc(q.id)}" data-answer="${n}" aria-label="${i+1}번 문항 ${n}번 선택" aria-pressed="${session.answers[q.id]===n}" ${locked?'disabled':''}>${n}</button>`).join('')}<span class="omr-flag">${session.flags[q.id]?'★':''}</span></div>`;}).join('');$('omrGrid').scrollTop=oldScroll;
 $('qNav').innerHTML=list.map((q,i)=>{const locked=['paused','break'].includes(session.status)||(session.status==='running'&&!settings.allowBack&&i<session.index);const rv=reviewing()?'r-'+verdict(q):'';return `<button data-go="${i}" class="${session.answers[q.id]&&!rv?'answered':''} ${rv} ${i===session.index?'current':''} ${session.flags[q.id]?'flagged':''}" aria-label="${i+1}번 문항${rv?' '+{"r-correct":'정답',"r-wrong":'오답',"r-blank":'미응답',"r-ungraded":'미채점'}[rv]:session.answers[q.id]?' 응답함':''}" ${i===session.index?'aria-current="true"':''} ${locked?'disabled':''}>${String(i+1).padStart(2,'0')}</button>`;}).join('');
}
function renderTimer(){const section=plan[session.sectionIndex],status=session.status;if(!section)return;const remaining=status==='ready'?section.minutes*60000:status==='paused'?session.remaining:status==='finished'?0:Math.max(0,session.deadline-Date.now());$('timer').textContent=formatTime(remaining);$('timer').classList.toggle('warning-timer',status==='running'&&remaining<=60000);$('timerLabel').textContent=status==='break'?'다음 영역 시작까지':status==='paused'?'일시정지':status==='finished'?'시험 종료':'영역별 남은 시간';const total=status==='break'?settings.breakSeconds*1000:section.minutes*60000;$('timeProgress').style.width=`${Math.min(100,remaining/Math.max(1,total)*100)}%`;}
function render(){if(!plan.length)return;const q=qNow();const key=`${q?.id}-${session.status}`;if(key!==lastRender){renderQuestion();lastRender=key;}
 $('sectionTitle').textContent=plan[session.sectionIndex].name;$('examName').textContent=`${project.name} · ${session.sectionIndex+1}/${plan.length} 영역`;$('modeBadge').textContent=settings.mode==='exam'?'실전 모드':'연습 모드';$('omrPanel').hidden=!settings.showOmr;$('sectionSteps').innerHTML=plan.map((s,i)=>reviewing()?`<button data-section="${i}" class="${i===session.sectionIndex?'now':''}">${esc(s.name)} ${scoreQuestions(s.questions,session).correct}/${s.questions.length}</button>`:`<span class="${i<session.sectionIndex&&session.status!=='ready'?'done':i===session.sectionIndex?'now':''}">${esc(s.name)} ${s.questions.length}</span>`).join('');$('eraserBtn').hidden=!!settings.strictTools;$('undoPaintBtn').hidden=!!settings.strictTools;if(settings.strictTools&&paintMode!=='pen')setPaintMode('pen');$('scratchCaption').textContent=settings.clearTools?'문항 이동 시 메모·그림·계산기 초기화':'메모·그림·계산 내용 유지';
 $('startBtn').hidden=!['ready','finished'].includes(session.status);$('startBtn').textContent=session.status==='finished'?'다시 시작':'시험 시작';$('pauseBtn').hidden=!isActive()||settings.mode==='exam';$('pauseBtn').textContent=session.status==='paused'?'계속하기':'일시정지';$('finishBtn').textContent=session.status==='finished'?'결과 보기':'제출';$('finishBtn').disabled=session.status==='ready';$('libraryBtn').disabled=isActive();$('settingsBtn').disabled=isActive();
 $('prevBtn').disabled=reviewing()?(reviewList&&reviewPos()>=0?reviewPos()===0:(session.index===0&&session.sectionIndex===0)):session.index===0||['paused','break'].includes(session.status)||(session.status==='running'&&!settings.allowBack);$('nextBtn').disabled=['paused','break'].includes(session.status);$('nextBtn').textContent=reviewing()&&reviewList&&reviewPos()>=0?(reviewPos()===reviewList.length-1?'결과 보기':'다음 걸러진 문항 →'):session.index===plan[session.sectionIndex].questions.length-1?(session.sectionIndex===plan.length-1?(reviewing()?'결과 보기':'시험 제출'):'다음 영역 →'):'다음 문제 →';
 $('questionHint').textContent=session.status==='ready'?'준비된 문제를 확인한 뒤 시험을 시작하세요.':session.status==='finished'?(reviewList&&reviewPos()>=0?`걸러진 문항 복기 · ${reviewPos()+1} / ${reviewList.length} (${[resultFilter.section==='all'?'전체 영역':plan[Number(resultFilter.section)]?.name,resultFilter.verdict==='all'?'':{correct:'정답',incorrect:'오답+미응답',wrong:'오답',blank:'미응답',ungraded:'미채점',flag:'다시 보기'}[resultFilter.verdict]].filter(Boolean).join(' · ')})`:'복기 중 · 내 답과 정답을 함께 표시합니다. 번호 색: 초록 정답, 빨강 오답, 회색 미응답.'):settings.allowBack?'현재 영역 안에서 문항을 이동할 수 있습니다.':'다음으로 이동하면 이전 답안을 수정할 수 없습니다.';
 const overlay=$('examOverlay');overlay.hidden=!['paused','break'].includes(session.status);if(!overlay.hidden)overlay.innerHTML=session.status==='paused'?'<h2>일시정지</h2><p>계속하기를 누르면 남은 시간부터 이어집니다.</p>':`<div class="eyebrow">다음 영역 안내</div><h2>${esc(plan[session.sectionIndex].name)}</h2><p>${plan[session.sectionIndex].questions.length}문항 · ${plan[session.sectionIndex].minutes}분<br>상단 안내 시간이 끝나면 자동으로 시작합니다.</p>`;
 $('memo').disabled=['paused','break'].includes(session.status);$('paintCanvas').style.pointerEvents=['paused','break'].includes(session.status)?'none':'';renderAnswers();renderTimer();
}
$('answerChoices').onclick=e=>{const b=e.target.closest('[data-answer]');if(b)choose(Number(b.dataset.answer));};
$('qNav').onclick=e=>{const b=e.target.closest('[data-go]');if(b)navigate(Number(b.dataset.go));};
$('omrGrid').onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.go!==undefined)navigate(Number(b.dataset.go));else if(b.dataset.answer)choose(Number(b.dataset.answer),b.dataset.q);};
$('clearAnswerBtn').onclick=()=>{if(canAnswer()){session.answers[qNow().id]=null;renderAnswers();queueSave();}};
$('flagBtn').onclick=()=>{const q=qNow();if(q){session.flags[q.id]=!session.flags[q.id];renderAnswers();queueSave();}};
$('prevBtn').onclick=()=>{if(reviewing()&&reviewList){const p=reviewPos();if(p>0)return goTo(...reviewList[p-1]);if(p===0)return;reviewList=null;}if(reviewing()&&session.index===0){const s=session.sectionIndex-1;if(s>=0)goTo(s,plan[s].questions.length-1);return;}navigate(session.index-1);};
$('sectionSteps').onclick=e=>{const b=e.target.closest('[data-section]');if(b&&reviewing())reviewList=null,goTo(Number(b.dataset.section),0);};
$('nextBtn').onclick=async()=>{sync();if(reviewing()&&reviewList){const p=reviewPos();if(p<0)reviewList=null;else if(p<reviewList.length-1)return goTo(...reviewList[p+1]);else{reviewList=null;return showResults();}}if(session.index<plan[session.sectionIndex].questions.length-1)return navigate(session.index+1);if(session.status==='finished'){if(session.sectionIndex<plan.length-1)return goTo(session.sectionIndex+1,0);return showResults();}if(session.status==='ready')return toast('시험 시작을 누르면 영역별로 진행됩니다.');if(session.sectionIndex===plan.length-1)return finish();const sectionAtPrompt=session.sectionIndex;if(await ask('현재 영역을 제출할까요?','제출한 영역으로 돌아갈 수 없습니다. 미응답 문항도 그대로 제출됩니다.','영역 제출')){sync();if(session.status!=='running'||session.sectionIndex!==sectionAtPrompt)return;advanceSection(session,plan,settings,Date.now());resetScratch();lastRender='';render();queueSave();}};
$('startBtn').onclick=async()=>{if(session.status==='finished'&&!await ask('새 시험을 시작할까요?','현재 답안과 풀이 시간은 새 시험으로 교체됩니다. 필요한 결과는 먼저 CSV로 저장하세요.','다시 시작'))return;revealedKeys=new Set();startSession(session,plan,Date.now());resetScratch();lastRender='';render();queueSave();};
$('pauseBtn').onclick=()=>{sync();if(settings.mode==='exam')return;if(session.status==='paused')resumeSession(session,Date.now());else pauseSession(session,plan,Date.now());lastRender='';render();queueSave();};
async function finish(){sync();if(session.status==='finished')return showResults();if(!isActive())return;const unanswered=project.questions.filter(q=>!session.answers[q.id]).length;if(await ask('시험을 제출할까요?',`미응답 ${unanswered}문항이 있습니다. 남은 영역을 포함해 시험을 종료하고 결과를 확인합니다.`,'시험 제출')){sync();completeSession(session,plan,Date.now());lastRender='';render();queueSave();showResults();}}
$('finishBtn').onclick=finish;$('zoomSelect').onchange=applyZoom;
$('fullscreenBtn').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{toast('전체 화면을 지원하지 않는 창입니다. 브라우저의 F11을 사용해 주세요.');}};
for(const dialog of document.querySelectorAll('dialog'))dialog.addEventListener('click',e=>{if(e.target===dialog&&dialog.id!=='confirmDialog'){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$(b.dataset.close).close());$('guideBtn').onclick=()=>$('guideDialog').showModal();

function showSettings(){
 $('settingsBody').innerHTML=`<label class="field">풀이 방식<select id="modeInput"><option value="practice">연습 모드 · 일시정지 가능</option><option value="exam">실전 모드 · 일시정지 불가</option></select></label><div class="notice">실제 SKCT 인지검사는 5개 영역 × 20문항 × 15분(총 75분)이며 영역 사이 휴식이 없습니다. 문항을 배정한 영역만 시험에 포함됩니다. 지원 전형의 안내가 다르면 수정하세요.</div><h3 style="font-size:16px">영역 순서와 제한 시간 (분)</h3><div id="sectionRows"></div><label class="field">영역 사이 안내 시간 (초)<input id="breakInput" type="number" min="0" max="600" step="1" value="${settings.breakSeconds}"></label><label class="check-field"><input id="backInput" type="checkbox" ${settings.allowBack?'checked':''}>같은 영역 안에서 이전 문항으로 돌아가기 허용</label><label class="check-field"><input id="clearToolsInput" type="checkbox" ${settings.clearTools?'checked':''}>문항 이동 시 메모장·그림판·계산기 비우기</label><label class="check-field"><input id="omrInput" type="checkbox" ${settings.showOmr?'checked':''}>연습용 OMR 답안표 표시</label><label class="check-field"><input id="strictInput" type="checkbox" ${settings.strictTools?'checked':''}>실전 도구 제한 · 그림판은 전체 지우기만 (지우개·되돌리기 숨김)</label><label class="field">영역당 출제 문항<select id="limitInput"><option value="0">준비한 문항 모두</option><option value="${EXAM_SPEC.questionsPerSection}">앞에서부터 ${EXAM_SPEC.questionsPerSection}문항 (실전)</option></select></label><div class="dialog-actions"><button id="presetReal">실전 규격 적용</button><button id="saveSettings" class="primary">설정 적용</button></div>`;
 let sections=structuredClone(settings.sections);
 const draw=()=>{$('sectionRows').innerHTML=sections.map((s,i)=>`<div class="section-settings"><span>${i+1}. ${esc(s.name)} <small class="muted">${project.questions.filter(q=>q.section===s.id).length}문항 준비</small></span><label><input aria-label="${esc(s.name)} 제한 시간 분" data-minutes="${s.id}" type="number" min="0.1" max="180" step="0.1" value="${s.minutes}"></label><button data-up="${i}" ${i===0?'disabled':''} aria-label="${esc(s.name)} 순서 올리기">↑</button></div>`).join('');};draw();
 $('sectionRows').oninput=e=>{const s=sections.find(s=>s.id===e.target.dataset.minutes);if(s)s.minutes=Number(e.target.value);};$('sectionRows').onclick=e=>{const b=e.target.closest('[data-up]');if(!b)return;const i=Number(b.dataset.up);if(i>0){[sections[i-1],sections[i]]=[sections[i],sections[i-1]];draw();}};
 $('modeInput').value=settings.mode;$('limitInput').value=String(settings.limitPerSection||0);
 $('presetReal').onclick=()=>{sections=DEFAULT_SECTIONS.map(s=>({...s,minutes:EXAM_SPEC.minutes}));draw();$('modeInput').value='exam';$('backInput').checked=false;$('omrInput').checked=false;$('strictInput').checked=true;$('clearToolsInput').checked=true;$('limitInput').value=String(EXAM_SPEC.questionsPerSection);$('breakInput').value=60;toast(`실전 규격: 5개 영역 × ${EXAM_SPEC.questionsPerSection}문항 × ${EXAM_SPEC.minutes}분. ‘설정 적용’을 눌러 저장하세요.`);};$('modeInput').onchange=()=>{if($('modeInput').value==='exam'){$('backInput').checked=false;$('omrInput').checked=false;$('strictInput').checked=true;}else{$('backInput').checked=true;$('omrInput').checked=true;$('strictInput').checked=false;}};
 $('saveSettings').onclick=async()=>{const gap=Number($('breakInput').value);if(sections.some(s=>!Number.isFinite(s.minutes)||s.minutes<.1||s.minutes>180)||!Number.isInteger(gap)||gap<0||gap>600)return toast('영역 시간은 0.1~180분, 안내 시간은 0~600초로 입력하세요.');if(session.status==='finished'&&!await ask('설정을 바꿀까요?','완료된 시험은 초기화됩니다. 필요한 결과는 먼저 저장하세요.','설정 적용'))return;settings={mode:$('modeInput').value,allowBack:$('backInput').checked,showOmr:$('omrInput').checked,clearTools:$('clearToolsInput').checked,strictTools:$('strictInput').checked,limitPerSection:Number($('limitInput').value)||0,breakSeconds:gap,sections};plan=planFor(project,settings);session=newSession();lastRender='';render();queueSave();$('settingsDialog').close();toast('시험 설정을 적용했습니다.');};$('settingsDialog').showModal();
}
$('settingsBtn').onclick=showSettings;

function renderCalculator(){ $('calcHistory').textContent=calculator.history;$('calcDisplay').textContent=calculator.display;}
$('calcKeys').innerHTML=['C','←','±','÷','7','8','9','×','4','5','6','−','1','2','3','+','0','00','.','='].map(n=>`<button data-key="${n}" class="${n==='='?'equals':['÷','×','−','+'].includes(n)?'operator':''}" aria-label="${n==='←'?'계산기 한 글자 지우기':n==='C'?'계산기 초기화':n==='±'?'계산기 부호 바꾸기':n}">${n}</button>`).join('');
$('calcKeys').onclick=e=>{const b=e.target.closest('[data-key]');if(b){calculator.press(b.dataset.key);renderCalculator();$('calculator').focus({preventScroll:true});}};
$('calculator').addEventListener('keydown',e=>{const map={'Enter':'=','=':'=','Escape':'C','Backspace':'←','/':'÷','*':'×','-':'−','+':'+','.':'.','%':'%'};const key=/^\d$/.test(e.key)?e.key:map[e.key];if(key){e.preventDefault();e.stopPropagation();calculator.press(key);renderCalculator();}});
$('memo').oninput=()=>{scratch.memo=$('memo').value;queueSave();};
function showScratchTab(paint){$('memo').hidden=paint;$('paintArea').hidden=!paint;$('memoTab').classList.toggle('active',!paint);$('paintTab').classList.toggle('active',paint);$('memoTab').setAttribute('aria-pressed',!paint);$('paintTab').setAttribute('aria-pressed',paint);if(paint)drawPaint();}
$('memoTab').onclick=()=>showScratchTab(false);$('paintTab').onclick=()=>showScratchTab(true);
$('clearScratchBtn').onclick=async()=>{const paint=!$('paintArea').hidden;if(paint?scratch.strokes.length:scratch.memo){if(!await ask(paint?'그림을 지울까요?':'메모를 지울까요?','현재 작성한 내용을 비웁니다.','지우기'))return;}if(paint){scratch.strokes=[];drawPaint();}else{scratch.memo='';$('memo').value='';}queueSave();};
function drawPaint(){const c=$('paintCanvas'),ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height);for(const stroke of scratch.strokes){if(!stroke.points.length)continue;ctx.globalCompositeOperation=stroke.mode==='eraser'?'destination-out':'source-over';ctx.strokeStyle='#263247';ctx.lineWidth=stroke.size*c.width;ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();const first=stroke.points[0];ctx.moveTo(first.x*c.width,first.y*c.height);for(const p of stroke.points)ctx.lineTo(p.x*c.width,p.y*c.height);if(stroke.points.length===1)ctx.lineTo(first.x*c.width+.1,first.y*c.height);ctx.stroke();}ctx.globalCompositeOperation='source-over';}
const point=e=>{const r=$('paintCanvas').getBoundingClientRect();return{x:Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),y:Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))};};
$('paintCanvas').onpointerdown=e=>{if(e.button!==0||['paused','break'].includes(session.status))return;e.preventDefault();$('paintCanvas').setPointerCapture(e.pointerId);const width=$('paintCanvas').getBoundingClientRect().width;activeStroke={mode:paintMode,size:(paintMode==='eraser'?18:Number($('penSize').value))/width,points:[point(e)]};scratch.strokes.push(activeStroke);drawPaint();};
$('paintCanvas').onpointermove=e=>{if(activeStroke){activeStroke.points.push(point(e));drawPaint();}};
function endStroke(){activeStroke=null;queueSave();}$('paintCanvas').onpointerup=endStroke;$('paintCanvas').onpointercancel=endStroke;
function setPaintMode(mode){paintMode=mode;for(const [id,value]of [['penBtn','pen'],['eraserBtn','eraser']]){$(id).classList.toggle('active',value===mode);$(id).setAttribute('aria-pressed',value===mode);}}
$('penBtn').onclick=()=>setPaintMode('pen');$('eraserBtn').onclick=()=>setPaintMode('eraser');$('undoPaintBtn').onclick=()=>{scratch.strokes.pop();drawPaint();queueSave();};
let topZ=30;
for(const id of ['calculatorPanel','scratchPanel']){const panel=$(id),handle=panel.querySelector('.drag-handle');let drag=null;
 handle.onpointerdown=e=>{if(e.button!==0||e.target.closest('button,select,input'))return;const r=panel.getBoundingClientRect();drag={dx:e.clientX-r.left,dy:e.clientY-r.top};panel.classList.add('floating');panel.style.width=`${r.width}px`;panel.style.left=`${r.left}px`;panel.style.top=`${r.top}px`;panel.style.zIndex=++topZ;handle.setPointerCapture(e.pointerId);};
 handle.onpointermove=e=>{if(drag){panel.style.left=`${Math.max(0,Math.min(window.innerWidth-panel.offsetWidth,e.clientX-drag.dx))}px`;panel.style.top=`${Math.max(0,Math.min(window.innerHeight-70,e.clientY-drag.dy))}px`;}};handle.onpointerup=()=>drag=null;handle.onpointercancel=()=>drag=null;
}
$('resetToolsBtn').onclick=()=>{for(const id of ['calculatorPanel','scratchPanel']){$(id).classList.remove('floating');$(id).removeAttribute('style');}};

// Result filters survive re-rendering (e.g. after a key is corrected).
let resultFilter={section:'all',verdict:'all'};
// When a review starts from a filtered list, prev/next walk only that list.
let reviewList=null;
function filteredList(){if(resultFilter.section==='all'&&resultFilter.verdict==='all')return null;return plan.flatMap((s,si)=>s.questions.map((q,i)=>rowVisible(si,q)?[si,i]:null)).filter(Boolean);}
function reviewPos(){return reviewList?reviewList.findIndex(([s,i])=>s===session.sectionIndex&&i===session.index):-1;}
const VERDICT_LABEL={correct:'정답',wrong:'오답',blank:'미응답',ungraded:'미채점'};
function resultFilterBar(){
 const rows=plan.flatMap((s,si)=>s.questions.map(q=>({si,v:verdict(q),f:!!session.flags[q.id]})));
 const inSec=rows.filter(r=>resultFilter.section==='all'||r.si===Number(resultFilter.section));
 const count=v=>inSec.filter(r=>v==='all'?true:v==='flag'?r.f:v==='incorrect'?r.v==='wrong'||r.v==='blank':r.v===v).length;
 const secTabs=[['all','전체',rows.length],...plan.map((s,si)=>[String(si),s.name,s.questions.length])].map(([k,n,c])=>`<button data-filter-section="${k}" aria-pressed="${resultFilter.section===k}" class="${resultFilter.section===k?'on':''}">${esc(n)} <small>${c}</small></button>`).join('');
 const vTabs=[['all','전체'],['correct','정답'],['incorrect','오답+미응답'],['wrong','오답'],['blank','미응답'],['ungraded','미채점'],['flag','★ 다시 보기']].map(([k,n])=>`<button data-filter-verdict="${k}" aria-pressed="${resultFilter.verdict===k}" class="${resultFilter.verdict===k?'on':''} ${k}">${n} <small>${count(k)}</small></button>`).join('');
 return `<div class="result-filters"><div class="filter-row" role="group" aria-label="영역 필터">${secTabs}</div><div class="filter-row" role="group" aria-label="결과 필터">${vTabs}${inSec.length&&count(resultFilter.verdict)?`<button id="reviewFiltered" class="primary review-start">이 목록 복기 시작 (${count(resultFilter.verdict)})</button>`:''}</div></div>`;
}
function rowVisible(si,q){if(resultFilter.section!=='all'&&si!==Number(resultFilter.section))return false;const v=verdict(q);switch(resultFilter.verdict){case 'all':return true;case 'flag':return !!session.flags[q.id];case 'incorrect':return v==='wrong'||v==='blank';default:return v===resultFilter.verdict;}}
function sectionSummary(){return `<table class="result-table section-result"><thead><tr><th>영역</th><th>응답</th><th>정답/채점</th><th>풀이 시간</th><th>문항당 평균</th></tr></thead><tbody>${plan.map((s,si)=>{const r=scoreQuestions(s.questions,session);return `<tr class="${resultFilter.section===String(si)?'on':''}"><td><button class="link-btn" data-filter-section="${si}" title="이 영역만 보기">${esc(s.name)}</button></td><td>${r.answered} / ${r.total}</td><td>${r.graded?`${r.correct} / ${r.graded} (${Math.round(r.correct/r.graded*100)}%)`:'—'}</td><td>${formatTime(r.time)}</td><td>${r.total?Math.round(r.time/r.total/1000)+'초':'—'}</td></tr>`;}).join('')}</tbody></table>`;}
function showResults(){if(session.status!=='finished')return;const all=scoreQuestions(project.questions,session);$('resultBody').innerHTML=`<p class="muted">${esc(project.name)} · ${session.finishedAt?new Date(session.finishedAt).toLocaleString('ko-KR'):''}</p><div class="result-stats"><div class="stat"><span>응답 문항</span><strong>${all.answered}<small> / ${all.total}</small></strong></div><div class="stat"><span>점수 · 미응답은 오답</span><strong>${all.correct}<small> / ${all.graded||all.total}</small></strong></div><div class="stat"><span>미채점</span><strong>${all.ungraded}</strong></div><div class="stat"><span>풀이 시간 합계</span><strong>${formatTime(all.time)}</strong></div></div>${sectionSummary()}<p class="inline-message">정답이 없는 문항은 미채점입니다. <b>정답표로 채점</b>으로 해설의 정답표 캡처를 읽어 한 번에 채점하거나, 표에서 정답을 바로 고칠 수 있습니다. 합격선이나 오답 감점을 추정하지 않습니다.</p>${resultFilterBar()}<div class="table-scroll"><table class="result-table" id="resultTable"><thead><tr><th>영역</th><th>문항</th><th>내 답</th><th>정답</th><th>결과</th><th>시간</th><th>복기</th></tr></thead><tbody>${plan.flatMap((s,si)=>s.questions.map((q,i)=>{if(!rowVisible(si,q))return '';const a=session.answers[q.id],status=!q.key?'미채점':a===q.key?'정답':a?'오답':'미응답';return `<tr><td>${esc(s.name)}</td><td>${i+1}</td><td>${a||'—'}</td><td><select class="key-input" data-result-key="${esc(q.id)}" aria-label="${esc(s.name)} ${i+1}번 정답"><option value="">—</option>${[1,2,3,4,5].map(n=>`<option value="${n}" ${q.key===n?'selected':''}>${n}</option>`).join('')}</select></td><td class="${status==='정답'?'result-good':['오답','미응답'].includes(status)?'result-bad':''}">${status}</td><td>${formatTime(session.times[q.id]||0)}</td><td><button data-review="${si}:${i}">보기${session.flags[q.id]?' ★':''}</button></td></tr>`;})).join('')}</tbody></table>${plan.some((s,si)=>s.questions.some(q=>rowVisible(si,q)))?'':'<p class="muted" style="padding:18px">조건에 맞는 문항이 없습니다.</p>'}</div><div class="dialog-actions"><button id="keyFromResults">정답표로 채점</button><button id="exportResults">결과 CSV 저장</button><button id="closeResults" class="primary">문제 다시 보기</button></div>`;
 $('resultBody').onchange=e=>{if(!e.target.dataset.resultKey)return;project.questions.find(q=>q.id===e.target.dataset.resultKey).key=Number(e.target.value)||null;persistProject();showResults();};
 $('resultBody').onclick=e=>{if(e.target.closest('#reviewFiltered')){const list=plan.flatMap((s,si)=>s.questions.map((q,i)=>rowVisible(si,q)?[si,i]:null)).filter(Boolean);if(!list.length)return;reviewList=filteredList();goTo(...list[0]);$('resultDialog').close();return;}const fs=e.target.closest('[data-filter-section]'),fv=e.target.closest('[data-filter-verdict]');if(fs||fv){if(fs)resultFilter.section=fs.dataset.filterSection===resultFilter.section&&fs.classList.contains('link-btn')?'all':fs.dataset.filterSection;if(fv)resultFilter.verdict=fv.dataset.filterVerdict;const sc=$('resultBody').querySelector('.table-scroll')?.scrollTop;showResults();return;}const b=e.target.closest('[data-review]');if(b){const [s,i]=b.dataset.review.split(':').map(Number);reviewList=filteredList();goTo(s,i);$('resultDialog').close();}};
 $('exportResults').onclick=()=>{const rows=[['영역','문항','원본','내 답','정답','결과','풀이 시간(초)','다시 보기']];for(const s of plan)s.questions.forEach((q,i)=>{const a=session.answers[q.id];rows.push([s.name,i+1,q.label,a||'',q.key||'',!q.key?'미채점':a===q.key?'정답':a?'오답':'미응답',Math.round((session.times[q.id]||0)/1000),session.flags[q.id]?'Y':'']);});download('SKCT_연습결과.csv','\uFEFF'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8');};$('closeResults').onclick=()=>$('resultDialog').close();$('keyFromResults').onclick=()=>openKeys(examKeyTarget);if(!$('resultDialog').open)$('resultDialog').showModal();
}
let keyDialog;const openKeys=(target,options)=>keyDialog.open(target,options);
const examKeyTarget={getQuestions:()=>project.questions,onApply:async keys=>{const report=applyAnswerKey(project.questions,keys);await persistProject();builder.syncKeys(project.questions);lastRender='';render();if(session.status==='finished')showResults();return report;}};
const builder=initBuilder({toast,ask,download,openKeys,getProject:()=>project,getSettings:()=>settings,onApply:async p=>{project=p;plan=planFor(project,settings);session=newSession();scratch={memo:'',strokes:[]};calculator.clear();renderCalculator();lastRender='';render();await persistProject();}});
$('libraryBtn').onclick=()=>builder.open();
keyDialog=initKeyDialog({toast,getPdfCanvas:()=>builder.pdfCanvas()});
document.addEventListener('visibilitychange',()=>{sync();persist();});window.addEventListener('pagehide',()=>{sync();persist();});
window.addEventListener('beforeunload',()=>{if(isActive()){sync();persist();}});
async function init(){try{const [savedProject,persisted]=await Promise.all([readRecord('project'),readRecord('state')]);if(savedProject?.questions?.length)project=savedProject;let immediate;try{immediate=JSON.parse(localStorage.getItem('skct-current-session')||'null');}catch{}const state=immediate?.projectId===project.id&&(!persisted||immediate.savedAt>=(persisted.savedAt||0))?immediate:persisted;if(state?.settings?.sections?.length)settings={...structuredClone(DEFAULT_SETTINGS),...state.settings};plan=planFor(project,settings);if(state?.projectId===project.id&&state.session&&plan[state.session.sectionIndex]?.questions[state.session.index]){session=state.session;scratch=state.scratch||scratch;}sync();$('saveStatus').textContent='이 기기에 자동 저장됨';}catch{$('saveStatus').textContent='저장 불가 · 내보내기로 백업하세요';}render();renderCalculator();setInterval(()=>{sync();renderTimer();if(['running','break'].includes(session.status))queueSave();},500);}
await init();
try{document.modelContext?.registerTool({name:'read_practice_status',title:'시험 연습 상태 확인',description:'현재 영역, 타이머 상태, 응답 문항 수를 읽습니다. 문제나 정답을 변경하지 않습니다.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input){if(input&&Object.keys(input).length)throw new Error('입력 항목이 없습니다.');return{status:session.status,section:plan[session.sectionIndex]?.name,question:session.index+1,answered:Object.values(session.answers).filter(Boolean).length,total:project.questions.length,remaining:$('timer').textContent};}});}catch{/* Optional browser API. */}

